{
  "name": "pairwise_weight_crossover_linear_rank",
  "intuition": "This builder combines the pairwise margin rank signal with a linear scaling weight, integrating the stable pair construction of all_pairs with a simple, nonnegative, and robust weight function that emphasizes margin differences while allowing easy tuning of the importance via extra parameters.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear_rank",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "gap_linear", "clamp"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_weight_crossover_linear_rank', 'weight_family': 'gap_linear_rank'})\n    # Use a simple linear weight proportional to margin gap\n    weight_raw = gap\n    # Clamp to ensure non-negativity and stability\n    weight = torch.clamp(weight_raw, min=0.0)\n    # Optional: scale weight with a parameter\n    scale = float(extra.get('weight_scale', 1.0))\n    weight = weight * scale\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'pairwise_weight_crossover_linear_rank', 'weight_family': 'gap_linear_rank'})"
}

{
  "name": "builder_all_pairs_gap_linear_clamp",
  "intuition": "Convert margin_rank_blend weighting to a gap_linear weighting with explicit clamping for numerical stability under reweight_only constraints.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_and_tiezone"
  },
  "operators_used": [
    "all_pairs",
    "clamp",
    "tie_zone_suppress"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Linear gap weighting with a small epsilon to ensure positivity\n    eps = 1e-6\n    raw_weight = gap.clamp_min(eps)\n    # Tie-zone suppression: zero weights where gap is too small (<= tie_zone)\n    tie_zone = float(extra.get('tie_zone', 0.05))\n    mask_tie_zone = raw_weight > tie_zone\n    weight = raw_weight * mask_tie_zone.to(raw_weight.dtype)\n    # Clamp weights for stability\n    clamp_min = float(extra.get('clamp_min', 0.1))\n    clamp_max = float(extra.get('clamp_max', 10.0))\n    weight = weight.clamp(clamp_min, clamp_max)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n"
}

