{
  "name": "builder_all_pairs_gap_linear_002",
  "intuition": "rule_based:all_pairs:reweight:gap_linear - simple linear weighting by positive objective gap with clamping",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_linear"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    raw = gap.clamp_min(0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    weight = raw\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}

{
  "name": "builder_all_pairs_gap_rank_blend_010",
  "intuition": "all pairs with weights blending gap magnitude and rank difference to emphasize pairs with large cost gaps and rank spread",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_rank_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_rank_blend"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    rank_span = (rank[b_idx, loser_idx] - rank[b_idx, winner_idx]).abs()\n    beta_rank = float(extra.get('beta_rank', 3.0))\n    alpha_gap = float(extra.get('alpha_gap', 1.0))\n    raw = (gap.clamp_min(0.0) * alpha_gap) * torch.sigmoid(beta_rank * rank_span)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n"
}

{
  "name": "builder_all_pairs_gap_regret_blend_001",
  "intuition": "Inject stable regret-based weighting with tie-zone suppression and clamping to ensure explicit constraint handling while preserving all-pairs topology.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_regret_blend",
    "constraint_family": "tiezone_clamp"
  },
  "operators_used": [
