    "clamp",
    "tiezone_filter"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    regret = feature_cache['regret']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})\n    eps = 1e-6\n    regret_diff = regret[b_idx, loser_idx] - regret[b_idx, winner_idx]\n    raw_weight = regret_diff.clamp_min(0.0)\n    tie_zone = 0.1\n    # Tie-zone suppression: zero weights for small regret differences\n    mask_tiezone = (raw_weight > tie_zone)\n    weight = raw_weight * mask_tiezone.to(raw_weight.dtype)\n    # Clamp weights to stabilize optimization\n    clamp_lo = 0.2\n    clamp_hi = 3.5\n    weight = weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})\n"
}

{
  "name": "builder_all_pairs_gap_regret_blend_000",
  "intuition": "reweight all pairs by blending gap and regret signals linearly, emphasizing regret-driven weighting",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_regret_blend",
    "constraint_family": "clamp_only"
  },
