  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    regret = feature_cache['regret']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    regret_span = regret[b_idx, loser_idx] - regret[b_idx, winner_idx]\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 1.0))\n    raw = alpha * gap.clamp_min(0.0) + beta * regret_span.clamp_min(0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})\n"
}

{
  "name": "builder_all_pairs_margin_regret_blend_010",
  "intuition": "reweight all pairs by a blend of margin and regret difference emphasizing margin normalized by regret gap",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "margin_regret_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "margin_regret_blend"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    regret = feature_cache['regret']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'margin_regret_blend'})\n    eps = 1e-6\n    lambda_regret = float(extra.get('lambda_regret', 1.0))\n    gamma = float(extra.get('gamma', 0.5))\n    margin_abs = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    regret_span = (regret[b_idx, loser_idx] - regret[b_idx, winner_idx]).abs() + eps\n    raw = (margin_abs / regret_span) * (1.0 + lambda_regret * (regret[b_idx, loser_idx] - regret[b_idx, winner_idx]))\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'margin_regret_blend'})\n"
}

{
  "name": "builder_all_pairs_gap_bandpass_010",
  "intuition": "reweight all pairs by a bandpass filter on the objective gap, emphasizing pairs with moderate gap sizes",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_bandpass",
    "constraint_family": "clamp_only"
