  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache.get('rank', None)\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_weight_gap_rank_blend_002', 'weight_family': 'gap_rank_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    rank_span = (rank[b_idx, loser_idx] - rank[b_idx, winner_idx]).abs() if rank is not None else torch.zeros_like(gap)\n    beta_rank = float(extra.get('beta_rank', 4.0))\n    alpha_gap = float(extra.get('alpha_gap', 1.0))\n    # Weight is gap times sigmoid of scaled rank difference\n    raw = gap.clamp_min(0.0) * alpha_gap * torch.sigmoid(beta_rank * rank_span)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    clamp_lo = float(extra.get('clamp_lo', 0.25))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'pairwise_weight_gap_rank_blend_002', 'weight_family': 'gap_rank_blend'})"
