  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    rank_span = (rank[b_idx, loser_idx] - rank[b_idx, winner_idx]).abs()\n    beta_rank = float(extra.get('beta_rank', 3.0))\n    alpha_gap = float(extra.get('alpha_gap', 1.0))\n    raw = (gap.clamp_min(0.0) * alpha_gap) * torch.sigmoid(beta_rank * rank_span)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    tiezone_width = float(extra.get('tiezone_width', 0.1))\n    # Suppress weights for pairs with near-zero gap within tiezone_width\n    tiezone_mask = (gap >= tiezone_width).to(dtype=weight.dtype)\n    weight = weight * tiezone_mask\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})"
}

