{
  "name": "gap_linear_blend_001",
  "intuition": "Combine a straightforward linear gap-based weighting with a monotonic transform of inverse regret to emphasize moderate objective differences while maintaining stability and simplicity in the pairwise weights.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "gap", "regret_inverse", "clamp"],
  "implementation_hint": {
    "expects": ["objective", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    regret = feature_cache['regret']\n    b_idx, winner_idx, loser_idx = (objective[:, :, None] < objective[:, None, :]).nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Normalize gap to emphasize moderate differences\n    gap_norm = gap / (1.0 + ops.abs(gap))\n    # Use inverse regret with a monotonic transform for stability\n    regret_inv = 1.0 / (1.0 + ops.abs(regret[b_idx, loser_idx] - regret[b_idx, winner_idx]))\n    raw_weight = gap_norm * regret_inv\n    weight = raw_weight.clamp_min(0.0).clamp_max(float(extra.get('clamp_hi', 4.0)))\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}

