    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    rank_diff = (rank[b_idx, loser_idx] - rank[b_idx, winner_idx]).abs().float()\n    eps = 1e-6\n    max_rank_diff = rank_diff.max() if rank_diff.numel() > 0 else 1.0\n    norm_rank_diff = rank_diff / (max_rank_diff + eps)\n    low = float(extra.get('band_low', 0.2))\n    high = float(extra.get('band_high', 0.6))\n    center = (low + high) * 0.5\n    half_width = (high - low) * 0.5 + eps\n    window = 1.0 - (norm_rank_diff - center).abs() / half_width\n    window = window.clamp(min=0.0, max=1.0)\n    raw = gap.clamp_min(0.0) * window\n    clamp_lo = float(extra.get('clamp_lo', 0.25))\n    clamp_hi = float(extra.get('clamp_hi', 4.0))\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})"
