{
  "name": "pairwise_gap_rank_blend_optimized",
  "intuition": "Fine-tuned the sigmoid beta and clamp bounds to enhance stability and emphasize pairs with significant objective gaps while maintaining nonnegative, finite, and normalized weights suitable for reweight_only mode.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "clamp_only",
    "weight_family": "gap_rank_blend",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "clamp", "abs", "div", "nan_to_num"],
  "implementation_hint": {
    "expects": ["objective", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    regret = feature_cache['regret']\n    b_idx, winner_idx, loser_idx = (objective[:, :, None] < objective[:, None, :]).nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_regret_blend'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    regret_diff = (regret[b_idx, loser_idx] - regret[b_idx, winner_idx]).abs()\n    eps = 1e-6\n    beta = float(extra.get('weight_beta', 8.0))\n    inv_regret_weight = torch.sigmoid(beta * (1.0 / (regret_diff + eps) - 1.0))\n    raw = gap.clamp_min(0.0) * inv_regret_weight\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0)\n    clamp_lo = float(extra.get('clamp_lo', 0.2))\n    clamp_hi = float(extra.get('clamp_hi', 3.0))\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_rank_blend'})"
}

