{
  "name": "pairwise_gap_linear_reweight_v2",
  "intuition": "This builder combines the positive objective gap weighting from parent 0 with a monotonic inverse regret transform from parent 1, preserving stable pairwise topology while introducing a robust, nonnegative, and smoothly varying weight function that emphasizes meaningful objective differences and penalizes high regret disparity. It leverages the fixed all-pairs structure and enhances weight stability with explicit clamp bounds, aligning with reweight_only constraints.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_linear",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "sub", "clamp", "abs", "mul", "nan_to_num"],
  "implementation_hint": {
    "expects": ["objective", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    regret = feature_cache['regret']\n    b_idx, winner_idx, loser_idx = (objective[:, :, None] < objective[:, None, :]).nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'gap_linear_reweight_v2', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp(min=0.0)\n    regret_diff = (regret[b_idx, loser_idx] - regret[b_idx, winner_idx]).abs()\n    eps = 1e-6\n    inv_regret = 1.0 / (regret_diff + eps)\n    raw_weight = gap_pos * inv_regret\n    raw_weight = torch.nan_to_num(raw_weight, nan=0.0, posinf=0.0, neginf=0.0)\n    weight = raw_weight.clamp(min=0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'gap_linear_reweight_v2', 'weight_family': 'gap_linear'})"
}

